// Throwaway check of behaviour the shared suite does not cover. Deleted after use.
import { chromium } from '@playwright/test';
import { spawn } from 'node:child_process';

const PORT = 15731 + (process.pid % 500); // lanes share ports; derive a unique one
const BASE = `http://127.0.0.1:${PORT}`;
const server = spawn('node', ['harness/server.mjs', '--port', String(PORT)], { stdio: ['ignore', 'inherit', 'inherit'] });
const out = [];
const check = (name, ok, detail = '') => out.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ' — ' + detail : ''}`);

await new Promise((r) => setTimeout(r, 1200));
const browser = await chromium.launch();
const ctx = await browser.newContext();
const page = await ctx.newPage();
page.on('dialog', (d) => { out.push('FAIL  a dialog appeared'); d.dismiss(); });

// 1. The spec's own example deep link: q=port matches only note 1, but note 3 is selected.
await page.goto(`${BASE}/#q=port&note=3`);
await page.locator('#feed').waitFor();
check('example deep link: query restored', (await page.locator('#search').inputValue()) === 'port');
check('example deep link: feed strictly filtered', (await page.locator('#feed article.note').count()) === 1);
check('example deep link: fragment keeps the selection', /#q=port&note=3/.test(page.url()), page.url());
await page.fill('#search', '');
check('clearing the query brings the selection back', (await page.locator('#feed article.note[data-note-id="3"]').getAttribute('aria-current')) === 'true');
check('fragment drops q but keeps note', page.url().endsWith('#note=3'), page.url());

// 2. Avatar scheme validation.
await page.goto(BASE + '/');
await page.fill('#title', 'js avatar');
await page.fill('#body', 'x');
await page.fill('#avatar', "javascript:window.__xss='avatar'");
await page.click('#note-form button[type="submit"]');
check('javascript: avatar renders no img', (await page.locator('#feed article.note').first().locator('img.note-avatar').count()) === 0);
await page.fill('#title', 'http avatar');
await page.fill('#body', 'x');
await page.fill('#avatar', 'https://example.test/a.png');
await page.click('#note-form button[type="submit"]');
check('https avatar renders', (await page.locator('#feed article.note').first().locator('img.note-avatar').count()) === 1);

// 3. Ids continue the sequence across a reload, and formatting survives persistence.
await page.reload();
const ids = await page.locator('#feed article.note').evaluateAll((n) => n.map((e) => e.dataset.noteId));
check('ids continue the sequence', ids.join(',') === '8,7,6,5,4,3,2,1', ids.join(','));
await page.fill('#title', 'link note');
await page.fill('#body', 'see <a href="https://example.test/">it</a>\nline two');
await page.click('#note-form button[type="submit"]');
await page.reload();
const first = page.locator('#feed article.note').first();
check('link survives reload', (await first.locator('.note-body a[href="https://example.test/"]').count()) === 1);
check('newline became a break', (await first.locator('.note-body br').count()) === 1);
check('form cleared', (await page.locator('#avatar').inputValue()) === '');

// 4. Search matches title or body, case-insensitively; results line reflects the raw query.
await page.fill('#search', 'RIBEIRA');
check('case-insensitive body match', (await page.locator('#feed article.note').count()) === 1);
check('results line', (await page.locator('#results-line').textContent()) === 'results for "RIBEIRA"');
await page.fill('#search', '   ');
check('whitespace query is not a search', (await page.locator('#results-line').textContent()) === '');

// 5. Back/forward through the fragment.
